-- iPlays 2.0 MVP: training topics ("what are we working on today") and the
-- remaining 15 base exercises (25 in total).
--
--   exercise_topics     professional topics a coach picks for a session, such as
--                       depth passes, game vision, pressing. Separate from the
--                       broad category. Draft list until the pilot club's
--                       sporting director approves it (approved = false).
--   exercises.topics    up to 6 topic codes per exercise. A copy keeps the
--                       source's topics. set_exercise_topics() edits them with
--                       the same rights as editing the exercise.
--
-- The 15 new exercises are original content written for iPlays, like the first
-- 10: not copied from books, websites, videos, federation or club programmes.
-- review_status = 'pending_review' until a licensed coach approves each one.
-- The library grows later in reviewed batches per topic group.
--
-- Additive only. Idempotent (topics on conflict do nothing, exercises skipped
-- by title, topics of the first 10 set only while empty).
-- Rollback: supabase/rollback/20261106500000_exercise_topics_base_25.down.sql

create table if not exists public.exercise_topics (
  code text primary key check (code ~ '^[a-z_0-9]{2,30}$'),
  label text not null check (char_length(label) between 1 and 40),
  sort int not null,
  approved boolean not null default false
);
alter table public.exercise_topics enable row level security;
drop policy if exists exercise_topics_select on public.exercise_topics;
create policy exercise_topics_select on public.exercise_topics for select to authenticated using (true);
grant select on public.exercise_topics to authenticated;
revoke insert, update, delete on public.exercise_topics from anon, authenticated;

insert into public.exercise_topics (code, label, sort) values
  ('passing', 'מסירה וקבלה', 1),
  ('first_touch', 'קבלה ראשונה', 2),
  ('depth_pass', 'מסירות עומק', 3),
  ('scanning', 'ראיית משחק וסריקה', 4),
  ('switch_play', 'החלפת אגף', 5),
  ('combination', 'שילובים וקיר', 6),
  ('dribbling', 'כדרור ו־1 נגד 1 בהתקפה', 7),
  ('build_up', 'בניית התקפה מאחור', 8),
  ('finishing', 'בעיטה וסיום', 9),
  ('crossing', 'הגבהות וכדורי רוחב', 10),
  ('counter', 'מעבר להתקפה', 11),
  ('recovery', 'מעבר להגנה', 12),
  ('pressing', 'לחץ וחטיפה', 13),
  ('defend_1v1', 'הגנה אישית', 14),
  ('compact', 'הגנה קבוצתית ומרווחים', 15),
  ('set_pieces', 'מצבים נייחים', 16),
  ('gk', 'שוערות', 17),
  ('coordination', 'קואורדינציה ומהירות', 18),
  ('communication', 'תקשורת והובלה', 19)
on conflict (code) do nothing;

alter table public.exercises add column if not exists topics text[] not null default '{}';
create index if not exists exercises_topics_idx on public.exercises using gin (topics);

-- Keep topics valid (known codes, no duplicates, at most 6) and let a copy
-- inherit the source's topics.
create or replace function public.exercises_topics_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and new.copied_from is not null and coalesce(cardinality(new.topics), 0) = 0 then
    select x.topics into new.topics from exercises x where x.id = new.copied_from;
  end if;
  new.topics := coalesce(array(select distinct t from unnest(coalesce(new.topics, '{}')) t
                               where t in (select code from exercise_topics) order by t), '{}');
  if cardinality(new.topics) > 6 then raise exception 'too many topics'; end if;
  return new;
end $$;
drop trigger if exists exercises_topics_guard on public.exercises;
create trigger exercises_topics_guard before insert or update of topics on public.exercises
  for each row execute function public.exercises_topics_guard();

create or replace function public.set_exercise_topics(p_id uuid, p_topics text[])
returns void language plpgsql security definer set search_path = public as $$
declare v exercises;
begin
  select * into v from exercises where id = p_id;
  if not found or not can_write_exercise(v.scope, v.owner_id, v.club_id) then raise exception 'not allowed'; end if;
  update exercises set topics = coalesce(p_topics, '{}'), updated_at = now() where id = p_id;
end $$;
revoke all on function public.set_exercise_topics(uuid, text[]) from public, anon;
grant execute on function public.set_exercise_topics(uuid, text[]) to authenticated;
revoke all on function public.exercises_topics_guard() from public, anon, authenticated;

-- Topics for the first 10 base exercises (only where none were set yet).
update public.exercises x set topics = v.topics
from (values
  ('ריבוע מסירות: מוסר ורץ אחרי הכדור', array['passing','first_touch']::text[]),
  ('רונדו 4 נגד 1 בריבוע קטן', array['passing','scanning']::text[]),
  ('שערי קונוסים בזוגות', array['passing','communication']::text[]),
  ('כדרור סלאלום ושינוי כיוון', array['dribbling','coordination']::text[]),
  ('משחקון 3 נגד 3 לשערים קטנים', array['pressing','finishing','scanning']::text[]),
  ('4 נגד 4 עם שני שחקני צד', array['switch_play','passing','compact']::text[]),
  ('מעבר מהיר אחרי חטיפה: 3 נגד 2', array['counter','recovery','finishing']::text[]),
  ('הגנה 1 נגד 1: לכוון את התוקף לקו', array['defend_1v1']::text[]),
  ('סיומת אחרי מסירת רוחב', array['crossing','finishing']::text[]),
  ('שוער: עמידת מוצא ותגובה לבעיטות קרובות', array['gk']::text[])
) as v(title, topics)
where x.scope = 'iplays' and x.title = v.title and x.topics = '{}';

-- 15 more original base exercises (25 in total). Drafts until professional approval.
