select 'iplays', 'active', 'pending_review', v.*, null
from (values
('סריקה לפני קבלה: צבע הקונוס', 'שטח של 20 על 20 עם 6 קונוסים בשלושה צבעים מפוזרים. השחקנים בזוגות עם כדור, מוסרים וזזים בכל השטח. המאמן קורא צבע, ומי שמקבל את הכדור הבא חייב לקבל בכיוון קונוס בצבע הזה ולמסור משם. שלב ב: המאמן מרים צבע ביד בלי לקרוא, כך שחייבים להרים את הראש.', 'להסתכל מעבר לכתף לפני שהכדור מגיע, לא אחרי. קבלה ראשונה בכיוון הקונוס, לא מתחת לרגליים. מסירה רק אחרי שהגוף פתוח.', 'warmup', 1, 7, 16, 6, 16, 10, 'custom', 20, 20, array['קונוסים בשלושה צבעים','כדורים']::text[], array['scanning','first_touch','passing']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 4, "y": 4, "id": "e1"}, {"type": "cone", "x": 16, "y": 5, "id": "e2"}, {"type": "cone", "x": 10, "y": 10, "id": "e3"}, {"type": "cone", "x": 4, "y": 16, "id": "e4"}, {"type": "cone", "x": 16, "y": 15, "id": "e5"}, {"type": "cone", "x": 10, "y": 3, "id": "e6"}, {"type": "player", "x": 6, "y": 8, "team": "a", "id": "e7"}, {"type": "player", "x": 13, "y": 12, "team": "a", "id": "e8"}, {"type": "player", "x": 8, "y": 14, "team": "a", "id": "e9"}, {"type": "player", "x": 14, "y": 7, "team": "a", "id": "e10"}, {"type": "ball", "x": 6.8, "y": 8.6, "id": "e11"}], "lines": [{"type": "pass", "pts": [[6, 8], [13, 12]], "id": "l1"}, {"type": "run", "pts": [[8, 14], [10, 17]], "id": "l2"}, {"type": "run", "pts": [[14, 7], [17, 9]], "id": "l3"}]}'::jsonb),
('קואורדינציה בסולם וקונוסים ויציאה למסירה', 'שני מסלולים זהים: 6 קונוסים קטנים בשורה במרחק חצי מטר, ואחריהם שני קונוסים לזיגזג. בסוף המסלול שחקן מוסר שמחכה עם כדור. השחקן עובר את הקונוסים בצעדים קטנים (רגל אחת, שתי רגליים, הצידה), מבצע זיגזג, מקבל מסירה ומחזיר בנגיעה אחת, ועובר לסוף הטור. כל 3 דקות מחליפים את סוג הצעדים.', 'צעדים קצרים על כריות כפות הרגליים. ידיים עובדות עם הרגליים. להגיע למסירה בשליטה ולא במהירות מקסימלית.', 'warmup', 1, 6, 14, 4, 12, 10, 'custom', 12, 20, array['קונוסים קטנים','כדורים']::text[], array['coordination','passing']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 2, "y": 3, "id": "e1"}, {"type": "cone", "x": 3, "y": 3, "id": "e2"}, {"type": "cone", "x": 4, "y": 3, "id": "e3"}, {"type": "cone", "x": 5, "y": 3, "id": "e4"}, {"type": "cone", "x": 6, "y": 3, "id": "e5"}, {"type": "cone", "x": 7, "y": 3, "id": "e6"}, {"type": "cone", "x": 10, "y": 2, "id": "e7"}, {"type": "cone", "x": 12, "y": 4, "id": "e8"}, {"type": "player", "x": 17, "y": 3, "team": "n", "id": "e9"}, {"type": "ball", "x": 16.4, "y": 3.4, "id": "e10"}, {"type": "player", "x": 1, "y": 3, "team": "a", "id": "e11"}, {"type": "cone", "x": 2, "y": 9, "id": "e12"}, {"type": "cone", "x": 3, "y": 9, "id": "e13"}, {"type": "cone", "x": 4, "y": 9, "id": "e14"}, {"type": "cone", "x": 5, "y": 9, "id": "e15"}, {"type": "cone", "x": 6, "y": 9, "id": "e16"}, {"type": "cone", "x": 7, "y": 9, "id": "e17"}, {"type": "cone", "x": 10, "y": 8, "id": "e18"}, {"type": "cone", "x": 12, "y": 10, "id": "e19"}, {"type": "player", "x": 17, "y": 9, "team": "n", "id": "e20"}, {"type": "player", "x": 1, "y": 9, "team": "a", "id": "e21"}], "lines": [{"type": "run", "pts": [[1, 3], [8, 3]], "id": "l1"}, {"type": "run", "pts": [[8, 3], [10, 2], [12, 4], [15, 3]], "id": "l2"}, {"type": "pass", "pts": [[17, 3], [15, 3]], "id": "l3"}]}'::jsonb),
('משחק תופסת עם כדור ביד', 'שטח של 25 על 20. שני תופסים עם אפודות. שאר השחקנים מוסרים כדור ביד ביניהם. מי שמחזיק בכדור לא נתפס, ומי שנתפס בלי כדור הופך לתופס. אחרי 2 דקות עוברים לכדור ברגל: מי שמכדרר מוגן רק אם הכדור צמוד אליו.', 'לראות איפה התופסים לפני שמוסרים. לקרוא בשם לשחקן שמקבל. ליצור משולשים ולא לעמוד באותו קו.', 'warmup', 1, 6, 12, 8, 16, 8, 'custom', 20, 25, array['כדור','אפודות','קונוסים']::text[], array['scanning','coordination','communication']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 0.5, "y": 0.5, "id": "e1"}, {"type": "cone", "x": 24.5, "y": 0.5, "id": "e2"}, {"type": "cone", "x": 24.5, "y": 19.5, "id": "e3"}, {"type": "cone", "x": 0.5, "y": 19.5, "id": "e4"}, {"type": "player", "x": 6, "y": 6, "team": "a", "id": "e5"}, {"type": "player", "x": 12, "y": 4, "team": "a", "id": "e6"}, {"type": "player", "x": 18, "y": 8, "team": "a", "id": "e7"}, {"type": "player", "x": 8, "y": 14, "team": "a", "id": "e8"}, {"type": "player", "x": 16, "y": 15, "team": "a", "id": "e9"}, {"type": "player", "x": 21, "y": 12, "team": "a", "id": "e10"}, {"type": "player", "x": 11, "y": 10, "team": "b", "id": "e11"}, {"type": "player", "x": 17, "y": 4, "team": "b", "id": "e12"}, {"type": "ball", "x": 6.6, "y": 6.6, "id": "e13"}], "lines": [{"type": "pass", "pts": [[6, 6], [8, 14]], "id": "l1"}, {"type": "run", "pts": [[11, 10], [7, 12]], "id": "l2"}, {"type": "run", "pts": [[12, 4], [14, 8]], "id": "l3"}]}'::jsonb),
('רונדו 5 נגד 2 עם מסירה מפצלת', 'ריבוע של 14 על 14. חמישה שחקנים בחוץ ושניים באמצע. נקודה רגילה על 8 מסירות ברצף, ושתי נקודות על מסירה שעוברת בין שני השחקנים באמצע. מי שאיבד את הכדור נכנס לאמצע עם השחקן שהיה הכי הרבה זמן בפנים.', 'לחפש קודם את המסירה המפצלת, ורק אם היא סגורה למסור לצד. המקבל זז כדי לפתוח קו בין שני המגינים. מסירה חזקה וצמודה לקרקע.', 'rondo', 2, 9, 18, 7, 7, 12, 'custom', 14, 14, array['קונוסים','כדורים','אפודות']::text[], array['depth_pass','scanning','passing']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 0.5, "y": 0.5, "id": "e1"}, {"type": "cone", "x": 13.5, "y": 0.5, "id": "e2"}, {"type": "cone", "x": 13.5, "y": 13.5, "id": "e3"}, {"type": "cone", "x": 0.5, "y": 13.5, "id": "e4"}, {"type": "player", "x": 1, "y": 4, "team": "a", "id": "e5"}, {"type": "player", "x": 1, "y": 11, "team": "a", "id": "e6"}, {"type": "player", "x": 7, "y": 13.5, "team": "a", "id": "e7"}, {"type": "player", "x": 13, "y": 9, "team": "a", "id": "e8"}, {"type": "player", "x": 9, "y": 0.5, "team": "a", "id": "e9"}, {"type": "player", "x": 6, "y": 6, "team": "b", "id": "e10"}, {"type": "player", "x": 9, "y": 8, "team": "b", "id": "e11"}, {"type": "ball", "x": 1.6, "y": 4.6, "id": "e12"}], "lines": [{"type": "pass", "pts": [[1, 4], [13, 9]], "id": "l1"}, {"type": "run", "pts": [[9, 0.5], [12, 3]], "id": "l2"}]}'::jsonb),
('רונדו 4 נגד 2 עם מעבר לריבוע השני', 'שני ריבועים של 10 על 10 צמודים. בריבוע אחד 4 נגד 2. כשהשניים באמצע חוטפים, הם מוסרים לריבוע השני ורצים אליו יחד עם שני שחקנים מהארבעה שאיבדו, ושם מתחיל 4 נגד 2 חדש. שני השחקנים האחרים מחכים בצד.', 'אחרי חטיפה: מסירה ראשונה מהירה לצד השני. הצוות שאיבד לוחץ מיד בשניים. בתוך הריבוע: משולשים ולא קווים.', 'rondo', 3, 11, 18, 8, 10, 15, 'custom', 10, 20, array['קונוסים','כדורים','אפודות']::text[], array['pressing','counter','passing']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 0.5, "y": 0.5, "id": "e1"}, {"type": "cone", "x": 10, "y": 0.5, "id": "e2"}, {"type": "cone", "x": 19.5, "y": 0.5, "id": "e3"}, {"type": "cone", "x": 0.5, "y": 9.5, "id": "e4"}, {"type": "cone", "x": 10, "y": 9.5, "id": "e5"}, {"type": "cone", "x": 19.5, "y": 9.5, "id": "e6"}, {"type": "player", "x": 1, "y": 5, "team": "a", "id": "e7"}, {"type": "player", "x": 5, "y": 1, "team": "a", "id": "e8"}, {"type": "player", "x": 9, "y": 5, "team": "a", "id": "e9"}, {"type": "player", "x": 5, "y": 9, "team": "a", "id": "e10"}, {"type": "player", "x": 4, "y": 4, "team": "b", "id": "e11"}, {"type": "player", "x": 6, "y": 6, "team": "b", "id": "e12"}, {"type": "player", "x": 13, "y": 2, "team": "n", "id": "e13"}, {"type": "player", "x": 17, "y": 8, "team": "n", "id": "e14"}, {"type": "ball", "x": 5.6, "y": 6.6, "id": "e15"}], "lines": [{"type": "pass", "pts": [[6, 6], [13, 2]], "id": "l1"}, {"type": "run", "pts": [[4, 4], [14, 6]], "id": "l2"}]}'::jsonb),
('שמירת כדור 3 אזורים: לעבור דרך האמצע', 'מלבן של 36 על 20 מחולק לשלושה אזורים של 12 מטר. באזור הראשון 4 נגד 1, באזור האמצעי שחקן אחד מכל קבוצה, באזור השלישי 4 נגד 1 בצד ההפוך. הקבוצה עם הכדור צריכה להעביר אותו לאזור השני דרך השחקן שלה באמצע, או במסירה ארוכה מעליו. מגן נוסף נכנס לאזור שאליו הכדור הגיע.', 'השחקן באמצע מחפש מקום מאחורי המגן, עם גב פתוח לאזור הבא. לא למהר: להזיז את המגן עד שקו המסירה נפתח. מסירה ארוכה רק כשהאמצע סגור.', 'rondo', 3, 12, 19, 11, 12, 15, 'custom', 20, 36, array['קונוסים','כדורים','אפודות']::text[], array['build_up','scanning','depth_pass']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 0.5, "y": 0.5, "id": "e1"}, {"type": "cone", "x": 12, "y": 0.5, "id": "e2"}, {"type": "cone", "x": 24, "y": 0.5, "id": "e3"}, {"type": "cone", "x": 35.5, "y": 0.5, "id": "e4"}, {"type": "cone", "x": 0.5, "y": 19.5, "id": "e5"}, {"type": "cone", "x": 12, "y": 19.5, "id": "e6"}, {"type": "cone", "x": 24, "y": 19.5, "id": "e7"}, {"type": "cone", "x": 35.5, "y": 19.5, "id": "e8"}, {"type": "player", "x": 2, "y": 4, "team": "a", "id": "e9"}, {"type": "player", "x": 2, "y": 16, "team": "a", "id": "e10"}, {"type": "player", "x": 10, "y": 4, "team": "a", "id": "e11"}, {"type": "player", "x": 10, "y": 16, "team": "a", "id": "e12"}, {"type": "player", "x": 6, "y": 10, "team": "b", "id": "e13"}, {"type": "player", "x": 17, "y": 12, "team": "a", "id": "e14"}, {"type": "player", "x": 19, "y": 8, "team": "b", "id": "e15"}, {"type": "player", "x": 26, "y": 4, "team": "b", "id": "e16"}, {"type": "player", "x": 26, "y": 16, "team": "b", "id": "e17"}, {"type": "player", "x": 34, "y": 4, "team": "b", "id": "e18"}, {"type": "player", "x": 34, "y": 16, "team": "b", "id": "e19"}, {"type": "player", "x": 30, "y": 10, "team": "a", "id": "e20"}, {"type": "ball", "x": 10.5, "y": 4.7, "id": "e21"}], "lines": [{"type": "pass", "pts": [[10, 4], [17, 12]], "id": "l1"}, {"type": "pass", "pts": [[17, 12], [26, 16]], "id": "l2"}, {"type": "run", "pts": [[6, 10], [9, 7]], "id": "l3"}]}'::jsonb),
('מסירת עומק לריצה מאחורי קו', 'שני קונוסים מסמנים "קו הגנה" 15 מטר לפני שני שערים קטנים. מוסר עומד 10 מטר לפני הקו, ורץ עומד על הקו. הרץ עושה תנועה קצרה לכיוון המוסר ואז פורץ באלכסון מאחורי הקו. המוסר מוסר לחלל שלפניו, הרץ מקבל בתנועה ובועט לאחד השערים. מתחלפים תפקידים. שלב ב: מוסיפים מגן פסיבי על הקו.', 'המסירה הולכת לחלל, לא לרגליים. הרץ לא עובר את הקו לפני המסירה. קבלה ראשונה קדימה, לא עצירה.', 'technique', 2, 9, 18, 4, 12, 12, 'custom', 20, 30, array['קונוסים','שערים קטנים','כדורים']::text[], array['depth_pass','passing','first_touch']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 15, "y": 2, "id": "e1"}, {"type": "cone", "x": 15, "y": 18, "id": "e2"}, {"type": "minigoal", "x": 29.5, "y": 6, "rot": 90, "id": "e3"}, {"type": "minigoal", "x": 29.5, "y": 14, "rot": 90, "id": "e4"}, {"type": "player", "x": 5, "y": 10, "team": "a", "label": "מוסר", "id": "e5"}, {"type": "ball", "x": 5.8, "y": 10.4, "id": "e6"}, {"type": "player", "x": 15, "y": 8, "team": "a", "label": "רץ", "id": "e7"}, {"type": "mannequin", "x": 15, "y": 12, "id": "e8"}], "lines": [{"type": "run", "pts": [[15, 8], [13, 9], [22, 13]], "id": "l1"}, {"type": "pass", "pts": [[5.8, 10.4], [22, 13.5]], "id": "l2"}, {"type": "shot", "pts": [[23, 13.5], [29, 14]], "id": "l3"}]}'::jsonb),
('משולש מסירות: קבלה בגוף פתוח ומסירה לצד השני', 'שלושה קונוסים במשולש עם צלעות של 15 מטר ושחקן בכל קונוס, ובאמצע שחקן נוסף. הכדור עובר מקונוס לשחקן באמצע, שמקבל בגוף פתוח ומוסר לקונוס השלישי, לא לזה שמסר לו. מחליפים את השחקן באמצע כל דקה.', 'השחקן באמצע עומד בזווית ורואה שני קונוסים לפני הקבלה. קבלה ברגל הרחוקה. מסירה בנגיעה שנייה, בלי לעצור את הכדור.', 'technique', 2, 9, 18, 4, 8, 10, 'custom', 16, 16, array['קונוסים','כדורים']::text[], array['first_touch','switch_play','scanning']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 1, "y": 8, "id": "e1"}, {"type": "cone", "x": 15, "y": 1, "id": "e2"}, {"type": "cone", "x": 15, "y": 15, "id": "e3"}, {"type": "player", "x": 1, "y": 8, "team": "a", "id": "e4"}, {"type": "player", "x": 15, "y": 1, "team": "a", "id": "e5"}, {"type": "player", "x": 15, "y": 15, "team": "a", "id": "e6"}, {"type": "player", "x": 9, "y": 8, "team": "b", "label": "אמצע", "id": "e7"}, {"type": "ball", "x": 1.7, "y": 8.4, "id": "e8"}], "lines": [{"type": "pass", "pts": [[1.7, 8.4], [8.5, 8]], "id": "l1"}, {"type": "pass", "pts": [[9, 8], [15, 14.5]], "id": "l2"}]}'::jsonb),
('5 נגד 5 עם אזור עומק', 'מגרש של 40 על 30 עם שער ושוער בכל צד, ואזור של 8 מטר לפני כל שער. אסור להיכנס לאזור לפני הכדור: שחקן רשאי לרוץ לתוכו רק ברגע שיוצאת אליו מסירה. שער מתוך מסירה לאזור שווה שתי נקודות. 4 דקות למשחק.', 'המוסר מסתכל על הריצה, הרץ מסתכל על המוסר. ריצה באלכסון ולא ישר. ההגנה מחזיקה קו וסוגרת את המוסר.', 'ssg', 3, 10, 18, 10, 12, 16, 'custom', 30, 40, array['שערים','קונוסים','כדורים','אפודות']::text[], array['depth_pass','counter','finishing']::text[], '{"v": 1, "elements": [{"type": "goal", "x": 0.5, "y": 15, "rot": 90, "id": "e1"}, {"type": "goal", "x": 39.5, "y": 15, "rot": 90, "id": "e2"}, {"type": "gk", "x": 1.5, "y": 15, "id": "e3"}, {"type": "gk", "x": 38.5, "y": 15, "id": "e4"}, {"type": "cone", "x": 8, "y": 0.5, "id": "e5"}, {"type": "cone", "x": 8, "y": 29.5, "id": "e6"}, {"type": "cone", "x": 32, "y": 0.5, "id": "e7"}, {"type": "cone", "x": 32, "y": 29.5, "id": "e8"}, {"type": "player", "x": 10, "y": 10, "team": "a", "id": "e9"}, {"type": "player", "x": 14, "y": 20, "team": "a", "id": "e10"}, {"type": "player", "x": 20, "y": 8, "team": "a", "id": "e11"}, {"type": "player", "x": 22, "y": 18, "team": "a", "id": "e12"}, {"type": "player", "x": 27, "y": 14, "team": "a", "id": "e13"}, {"type": "player", "x": 29, "y": 10, "team": "b", "id": "e14"}, {"type": "player", "x": 29, "y": 20, "team": "b", "id": "e15"}, {"type": "player", "x": 24, "y": 24, "team": "b", "id": "e16"}, {"type": "player", "x": 18, "y": 14, "team": "b", "id": "e17"}, {"type": "player", "x": 12, "y": 5, "team": "b", "id": "e18"}, {"type": "ball", "x": 22.6, "y": 18.5, "id": "e19"}], "lines": [{"type": "run", "pts": [[27, 14], [35, 20]], "id": "l1"}, {"type": "pass", "pts": [[22.6, 18.5], [35, 20.5]], "id": "l2"}, {"type": "shot", "pts": [[35, 20.5], [39, 16]], "id": "l3"}]}'::jsonb),
('4 נגד 4 + 2: הגנה קבוצתית ומרווחים', 'שטח של 30 על 25 עם שני שערים קטנים בכל צד, ברוחב. 4 נגד 4, ושני שחקנים ניטרליים משחקים עם המחזיקה בכדור. הקבוצה המגינה מקבלת נקודה אם היא חוטפת ומבקיעה תוך 6 שניות. המאמן עוצר רק כשהמרווח בין שני המגינים הקרובים גדול מ־8 מטר.', 'לזוז יחד לצד של הכדור. השחקן הקרוב לוחץ, השני מכסה מאחוריו. לדבר: "אני לוחץ", "אני מכסה".', 'ssg', 3, 11, 18, 10, 10, 15, 'custom', 25, 30, array['שערים קטנים','קונוסים','כדורים','אפודות בשלושה צבעים']::text[], array['compact','pressing','communication']::text[], '{"v": 1, "elements": [{"type": "minigoal", "x": 0.5, "y": 6, "rot": 90, "id": "e1"}, {"type": "minigoal", "x": 0.5, "y": 19, "rot": 90, "id": "e2"}, {"type": "minigoal", "x": 29.5, "y": 6, "rot": 90, "id": "e3"}, {"type": "minigoal", "x": 29.5, "y": 19, "rot": 90, "id": "e4"}, {"type": "player", "x": 8, "y": 6, "team": "a", "id": "e5"}, {"type": "player", "x": 8, "y": 19, "team": "a", "id": "e6"}, {"type": "player", "x": 14, "y": 12, "team": "a", "id": "e7"}, {"type": "player", "x": 18, "y": 4, "team": "a", "id": "e8"}, {"type": "player", "x": 16, "y": 8, "team": "b", "id": "e9"}, {"type": "player", "x": 19, "y": 13, "team": "b", "id": "e10"}, {"type": "player", "x": 22, "y": 9, "team": "b", "id": "e11"}, {"type": "player", "x": 21, "y": 17, "team": "b", "id": "e12"}, {"type": "player", "x": 15, "y": 24, "team": "n", "id": "e13"}, {"type": "player", "x": 15, "y": 1, "team": "n", "id": "e14"}, {"type": "ball", "x": 18.6, "y": 4.6, "id": "e15"}], "lines": [{"type": "run", "pts": [[16, 8], [17.5, 5.5]], "id": "l1"}, {"type": "run", "pts": [[19, 13], [18, 8]], "id": "l2"}, {"type": "run", "pts": [[22, 9], [21, 6]], "id": "l3"}]}'::jsonb),
('מעבר להגנה: 3 נגד 3 עם חזרה מהירה', 'חצי מגרש. 3 תוקפים נגד 2 מגינים ושוער. שחקן מגן שלישי מתחיל בקו האמצע, ונכנס רק כשהמאמן מוסר את הכדור לתוקפים. אם המגינים חוטפים, הם תוקפים שני שערים קטנים בקו האמצע, והתוקפים חייבים לחזור ולהגן.', 'אחרי איבוד: הקרוב לוחץ את הכדור, השניים האחרים חוזרים למרכז, לא לכדור. המגן שנכנס רץ לכיוון השער, לא לכדור. מעכבים עד שהעזרה מגיעה.', 'transition', 3, 11, 18, 7, 10, 15, 'half', null, null, array['שער','שערים קטנים','קונוסים','כדורים','אפודות']::text[], array['recovery','compact','pressing']::text[], '{"v": 1, "elements": [{"type": "goal", "x": 52, "y": 34, "rot": 90, "id": "e1"}, {"type": "gk", "x": 50.5, "y": 34, "id": "e2"}, {"type": "minigoal", "x": 1, "y": 24, "rot": 90, "id": "e3"}, {"type": "minigoal", "x": 1, "y": 44, "rot": 90, "id": "e4"}, {"type": "player", "x": 30, "y": 24, "team": "a", "id": "e5"}, {"type": "player", "x": 28, "y": 34, "team": "a", "id": "e6"}, {"type": "player", "x": 30, "y": 44, "team": "a", "id": "e7"}, {"type": "player", "x": 42, "y": 28, "team": "b", "id": "e8"}, {"type": "player", "x": 42, "y": 40, "team": "b", "id": "e9"}, {"type": "player", "x": 4, "y": 34, "team": "b", "id": "e10"}, {"type": "player", "x": 20, "y": 34, "team": "n", "label": "מאמן", "id": "e11"}, {"type": "ball", "x": 21, "y": 34, "id": "e12"}], "lines": [{"type": "pass", "pts": [[21, 34], [28, 34]], "id": "l1"}, {"type": "run", "pts": [[4, 34], [38, 34]], "id": "l2"}, {"type": "dribble", "pts": [[28, 34], [36, 30]], "id": "l3"}]}'::jsonb),
('חטיפה ועומק: לנצל את הרגע שאחרי', 'שטח של 40 על 30 מחולק לשני חצאים. בחצי אחד 4 נגד 4 על שמירת כדור. בחצי השני, ליד שער עם שוער, מחכה חלוץ אחד מכל קבוצה. קבוצה שחוטפת צריכה למסור לחלוץ שלה בתוך 5 שניות, ושני שחקנים רצים לעזור לו לסיים. אחרי הסיום חוזרים לחצי הראשון.', 'המסירה הראשונה אחרי החטיפה: קדימה, אם אפשר. החלוץ זז לצד הפנוי לפני החטיפה. הקבוצה שאיבדה לוחצת מיד את המוסר.', 'transition', 3, 12, 19, 10, 12, 16, 'custom', 30, 40, array['שער','קונוסים','כדורים','אפודות']::text[], array['counter','depth_pass','pressing']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 20, "y": 0.5, "id": "e1"}, {"type": "cone", "x": 20, "y": 29.5, "id": "e2"}, {"type": "goal", "x": 39.5, "y": 15, "rot": 90, "id": "e3"}, {"type": "gk", "x": 38.5, "y": 15, "id": "e4"}, {"type": "player", "x": 5, "y": 8, "team": "a", "id": "e5"}, {"type": "player", "x": 5, "y": 22, "team": "a", "id": "e6"}, {"type": "player", "x": 14, "y": 8, "team": "a", "id": "e7"}, {"type": "player", "x": 14, "y": 22, "team": "a", "id": "e8"}, {"type": "player", "x": 8, "y": 14, "team": "b", "id": "e9"}, {"type": "player", "x": 11, "y": 18, "team": "b", "id": "e10"}, {"type": "player", "x": 4, "y": 15, "team": "b", "id": "e11"}, {"type": "player", "x": 16, "y": 15, "team": "b", "id": "e12"}, {"type": "player", "x": 28, "y": 10, "team": "a", "id": "e13"}, {"type": "player", "x": 28, "y": 20, "team": "b", "id": "e14"}, {"type": "ball", "x": 11.6, "y": 18.6, "id": "e15"}], "lines": [{"type": "pass", "pts": [[11.6, 18.6], [28, 20]], "id": "l1"}, {"type": "run", "pts": [[16, 15], [30, 16]], "id": "l2"}, {"type": "shot", "pts": [[28.5, 20], [39, 16]], "id": "l3"}]}'::jsonb),
('הגנה 2 נגד 2: לחץ וכיסוי', 'מסדרון של 20 על 15 עם קו סיום בכל צד. שני מגינים מוסרים לשני תוקפים ויוצאים אליהם. התוקפים מנסים לעבור את הקו בכדרור. המגן הקרוב לכדור לוחץ, והשני עומד באלכסון מאחוריו ומכסה. כשהכדור עובר לתוקף השני, מחליפים תפקידים.', 'זווית כיסוי: באלכסון, 3-4 מטר מאחורי הלוחץ. לא שני מגינים על אותו תוקף. להחליף לוחץ ומכסה תוך כדי מסירה, לא אחריה.', 'defending', 3, 10, 18, 4, 12, 12, 'custom', 15, 20, array['קונוסים','כדורים','אפודות']::text[], array['defend_1v1','compact','communication']::text[], '{"v": 1, "elements": [{"type": "cone", "x": 0.5, "y": 0.5, "id": "e1"}, {"type": "cone", "x": 19.5, "y": 0.5, "id": "e2"}, {"type": "cone", "x": 19.5, "y": 14.5, "id": "e3"}, {"type": "cone", "x": 0.5, "y": 14.5, "id": "e4"}, {"type": "player", "x": 4, "y": 5, "team": "a", "id": "e5"}, {"type": "player", "x": 4, "y": 10, "team": "a", "id": "e6"}, {"type": "ball", "x": 4.6, "y": 5.5, "id": "e7"}, {"type": "player", "x": 14, "y": 5, "team": "b", "id": "e8"}, {"type": "player", "x": 17, "y": 9, "team": "b", "id": "e9"}], "lines": [{"type": "run", "pts": [[14, 5], [8, 5]], "id": "l1"}, {"type": "run", "pts": [[17, 9], [11, 8]], "id": "l2"}, {"type": "pass", "pts": [[4.6, 5.5], [4, 10]], "id": "l3"}]}'::jsonb),
('שוער: יציאה לכדור עומק ומשחק רגל', 'חצי מגרש. מוסר בקו האמצע שולח כדורי עומק לאזור שבין קו ההגנה לשוער, ותוקף רץ אחריהם. השוער מחליט: לצאת ולהרחיק או לשלוט ברגל ולמסור לשחקן פנוי באגף, או להישאר בשער. אחר כך מוסר נוסף מאגף שולח כדור חוזר לשוער, והוא בונה התקפה לשחקן הפנוי.', 'עמידה גבוהה כשהכדור רחוק. החלטה מוקדמת וקריאה בקול: "שלי". נגיעה ראשונה הצידה, הרחק מהתוקף.', 'goalkeeping', 3, 11, 18, 3, 6, 12, 'half', null, null, array['שער','קונוסים','כדורים']::text[], array['gk','depth_pass','build_up']::text[], '{"v": 1, "elements": [{"type": "goal", "x": 52, "y": 34, "rot": 90, "id": "e1"}, {"type": "gk", "x": 48, "y": 34, "id": "e2"}, {"type": "player", "x": 28, "y": 34, "team": "n", "label": "מוסר", "id": "e3"}, {"type": "ball", "x": 29, "y": 34, "id": "e4"}, {"type": "player", "x": 34, "y": 26, "team": "b", "id": "e5"}, {"type": "cone", "x": 38, "y": 20, "id": "e6"}, {"type": "cone", "x": 38, "y": 48, "id": "e7"}, {"type": "player", "x": 44, "y": 10, "team": "a", "label": "פנוי", "id": "e8"}], "lines": [{"type": "pass", "pts": [[29, 34], [42, 32]], "id": "l1"}, {"type": "run", "pts": [[34, 26], [41, 31]], "id": "l2"}, {"type": "run", "pts": [[48, 34], [43, 32]], "id": "l3"}, {"type": "pass", "pts": [[43, 32], [44, 11]], "id": "l4"}]}'::jsonb),
('קרן קצרה: שלושה מסלולי ריצה', 'בועט קרן ושחקן קרוב אליו לקרן קצרה. שלושה תוקפים ברחבה עם מסלולים קבועים: נקודה קרובה, נקודה רחוקה, וחזרה לשפת הרחבה. המאמן מחליט לפני כל קרן אם היא קצרה או ישירה, בסימן יד. בשלב ב: שני מגינים ושוער.', 'כל תוקף יודע את המסלול שלו לפני הבעיטה. מתחילים לרוץ כשהבועט מרים יד. אחרי קרן קצרה: הגבהה מהשטח, לא מהקו.', 'set_pieces', 2, 10, 19, 5, 10, 12, 'half', null, null, array['שער','כדורים','אפודות']::text[], array['set_pieces','finishing','communication']::text[], '{"v": 1, "elements": [{"type": "goal", "x": 52, "y": 34, "rot": 90, "id": "e1"}, {"type": "gk", "x": 51, "y": 34, "id": "e2"}, {"type": "player", "x": 51.5, "y": 1, "team": "a", "label": "בועט", "id": "e3"}, {"type": "ball", "x": 52, "y": 0.8, "id": "e4"}, {"type": "player", "x": 46, "y": 4, "team": "a", "id": "e5"}, {"type": "player", "x": 42, "y": 26, "team": "a", "id": "e6"}, {"type": "player", "x": 40, "y": 40, "team": "a", "id": "e7"}, {"type": "player", "x": 36, "y": 32, "team": "a", "id": "e8"}, {"type": "player", "x": 47, "y": 30, "team": "b", "id": "e9"}, {"type": "player", "x": 46, "y": 38, "team": "b", "id": "e10"}], "lines": [{"type": "pass", "pts": [[52, 0.8], [46, 4]], "id": "l1"}, {"type": "pass", "pts": [[46, 4], [46, 36]], "id": "l2"}, {"type": "run", "pts": [[42, 26], [48, 31]], "id": "l3"}, {"type": "run", "pts": [[40, 40], [47, 42]], "id": "l4"}, {"type": "run", "pts": [[36, 32], [36, 24]], "id": "l5"}]}'::jsonb)
) as v(title, description, coaching_points, category, difficulty, age_from, age_to, players_min, players_max, duration_min, pitch_preset, area_w_m, area_l_m, equipment, topics, diagram)
